import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const plaguePhysicalScenarios=['plague-physical-ordinary','plague-physical-dedicated','plague-physical-immunity','plague-physical-dedicated-reflection'] as const;
export type PlaguePhysicalScenario=typeof plaguePhysicalScenarios[number];
export function isPlaguePhysicalScenario(name:string):name is PlaguePhysicalScenario{return plaguePhysicalScenarios.some(x=>x===name);}
export const PLAGUE='a2-p14-r1c1';
export function makePlaguePhysicalScenario(name:PlaguePhysicalScenario,players:{id:string;name:string}[],options:{level?:number;foreign?:boolean;follower?:'none'|'water'|'wight'}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string],immune=name==='plague-physical-immunity';for(const [i,p] of players.entries())assignCharacter(s,p.id,[immune?'白魔術師シェリム':options.foreign?'魔導王ガイナス':'不死王ガドューラ',immune?'不死王ガドューラ':'侍大将のシン','大神官ジル',immune?'魔導王ガイナス':'白魔術師シェリム'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+6-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.magic_level=20+(options.level??5)-gameStats(s,a).magic_level;
 const front=options.follower==='none'?null:takeCard(s,b,options.follower==='water'?'水竜':options.follower==='wight'?'ワイト':'メタルゴーレム'),rear=options.follower===undefined?takeCard(s,b,'兵士'):null,skeleton=options.follower==='none'?null:takeCard(s,c,'スケルトン'),own=name.endsWith('-reflection')?takeCard(s,a,'ゴブリン'):null,keep=[takeCard(s,a,PLAGUE),takeCard(s,b,'a2-p06-r1c1'),takeCard(s,b,'a2-p05-r3c1'),takeCard(s,d,'命運凶変'),...[front,rear,skeleton,own].filter((x):x is string=>!!x)];if(options.follower==='water')keep.push(takeCard(s,a,'必勝の祈り'));if(name.endsWith('-reflection'))keep.push(takeCard(s,b,'a2-p17-r3c2'));for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`PLAGUE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('PLAGUE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('PLAGUE_IDS');}
 for(const p of players){for(const cardInstanceId of (p.id===a?[own]:p.id===b?[front,rear]:p.id===c?[skeleton]:[]).filter((x):x is string=>!!x))act(p.id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(p.id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
